parameters.jsCode:
const urls = $('JobType Router').first().json.data.all_urls;
const chunksize = 50;
const splits = Math.max(1, Math.floor(urls.length/chunksize));

const blocks = Array(splits).fill(0)
 .map((_, idx) => {
 const block = urls
 .slice(
 idx * chunksize, 
 (idx * chunksize) + chunksize - 1
 )
 .map(url => {
 return {
 object: "block",
 type: "bulleted_list_item",
 bulleted_list_item: {
 rich_text: [
 { type: "text", text: { content: url } }
 ]
 }
 }
 });
 return { json: { block } }
 });

